const state={running:false,paused:false,over:false,score:[0,0],set:1,rally:1,serveSide:0,ballMode:'idle',ballPos:new THREE.Vector3(0,3.8,4.2),ballVel:new THREE.Vector3(),wind:0,windUntil:0,nextWind:0,targetX:0,targetZ:-4.6,lastTime:0,playerX:0,rivalX:0,playerJump:0,jumpVel:0,hitCooldown:0,serveCooldown:0,flash:0,shake:0,sound:true};
const clock=new THREE.Clock();let toastTimer;
function toast(msg,match=false){const el=$('#toast');el.textContent=msg;el.classList.toggle('match-point',match);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1250)}
function setServeButton(){const hit=$('#hitBtn');hit.textContent=state.ballMode==='idle'?(state.serveSide===0?'SERVE':'WAIT'):'VOLLEY';hit.style.opacity=state.ballMode==='idle'&&state.serveSide===1?'.56':'1'}
function setBall(x,y,z){ball.position.set(x,y,z);shadowBall.position.set(x,.002,z)}
function setupServe(){state.ballMode='idle';state.serveSide=state.score[0]>state.score[1]?1:0;state.ballPos.set(state.playerX,3.5,4.2);state.ballVel.set(0,0,0);setBall(...state.ballPos.toArray());setServeButton();$('#tip').innerHTML=state.serveSide===0?'<span>YOUR SERVE</span> Tap the big button to launch.':'<span>RIVAL SERVES</span> Move and volley it back!';}
function startMatch(){state.score=[0,0];state.set=1;state.rally=1;state.over=false;state.running=true;state.paused=false;state.playerX=0;state.rivalX=0;state.targetX=0;state.targetZ=-4.5;state.wind=0;state.nextWind=performance.now()/1000+5.5;$('#scoreMe').textContent='0';$('#scoreRival').textContent='0';$('#setNo').textContent='01';$('#rallyNo').textContent='01';$('#overlay').classList.add('hidden');$('#pauseBtn').textContent='Ⅱ';setupServe();toast('FIRST TO 5 · GOLDEN POCKET = BONUS');}
function endMatch(){state.over=true;state.running=false;const win=state.score[0]>state.score[1];$('#card').innerHTML=`<div class="eyebrow">${win?'ISLAND CHAMPION':'THE TIDE TURNS'}</div><h1>${win?'YOU<br><em>WIN</em>':'NICE<br><em>RALLY</em>'}</h1><p>${win?'The golden pocket is yours. The island lights are all yours tonight.':'The locals hold the court this round. Ready for a rematch?'}</p><div class="feature"><span class="feature-icon">🏐</span><span>FINAL SCORE <b>${state.score[0]} — ${state.score[1]}</b><br>Rallies played: ${state.rally}</span></div><button class="start-btn" id="restartBtn">PLAY AGAIN　↗</button><div class="micro">TIDEBREAK · ISLAND VOLLEY CLUB</div>`;$('#overlay').classList.remove('hidden');$('#restartBtn').onclick=startMatch;}
function point(winner,bonus=false){if(!state.running)return;state.score[winner]+=bonus?2:1;$('#scoreMe').textContent=state.score[0];$('#scoreRival').textContent=state.score[1];state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0');state.ballMode='point';state.ballVel.set(0,0,0);const text=winner===0?(bonus?'GOLDEN POCKET! +2':'YOUR POINT!'):(bonus?'RIVAL SCORES +2':'RIVAL POINT');toast(text,winner===0&&bonus);const won=state.score[winner]>=5;if(won){setTimeout(endMatch,1450);return}setTimeout(()=>{if(!state.running)return;state.serveSide=winner===0?1:0;setupServe();$('#tip').innerHTML=state.serveSide===0?'<span>YOUR SERVE</span> Tap the big button to launch.':'<span>RIVAL SERVES</span> Get ready to return!';},900);}
function serve(){if(!state.running||state.paused||state.ballMode!=='idle'||state.serveSide!==0)return;state.ballMode='flight';state.ballPos.set(state.playerX,3.2,4.05);state.ballVel.set((state.targetX-state.playerX)*.27,5.8,-8.7);ballMat.emissive.setHex(0x9a5c14);setServeButton();$('#tip').innerHTML='<span>MOVE + VOLLEY</span> Aim for the gold pocket!';}
function volley(){if(!state.running||state.paused||state.ballMode!=='flight'||state.hitCooldown>0)return;const d=ball.position.distanceTo(new THREE.Vector3(state.playerX,1.35+state.playerJump,4.2));if(ball.position.z>-.25&&ball.position.z<2.8&&d<2.45&&ball.position.y<4.2){state.hitCooldown=.48;const aimX=THREE.MathUtils.clamp(state.playerX+(state.playerX-state.rivalX)*.34,-3.6,3.6);state.ballVel.set((aimX-ball.position.x)*.85,5.6,-9.6);if(Math.abs(ball.position.x-state.targetX)<1.05)state.ballVel.x+=(state.targetX-state.ball.position.x)*.65;state.ballMode='flight';state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0');state.shake=.13;toast('CLEAN RETURN');}else if(ball.position.z>-1.2&&ball.position.z<3.6){toast('GET UNDER THE BALL');}}
function rivalHit(){if(state.ballMode!=='flight')return;state.ballVel.set((state.playerX-state.ball.position.x)*.38,4.8,9.3);state.ballPos.z=-.8;state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0');state.shake=.1;}
function triggerWind(now){state.wind=(Math.random()>.5?1:-1)*(.8+Math.random()*1.25);state.windUntil=now+3.1;state.nextWind=now+8+Math.random()*3;$('#windText').textContent=`TIDAL GUST · ${state.wind>0?'→':'←'}`;$('#wind').classList.add('on');toast(state.wind>0?'GUST FROM THE LEFT →':'← GUST FROM THE RIGHT');}
function update(dt,now){if(!state.running||state.paused)return;state.hitCooldown=Math.max(0,state.hitCooldown-dt);if(now>state.nextWind&&now>state.windUntil)triggerWind(now);if(now>state.windUntil&&state.wind!==0){state.wind=0;$('#wind').classList.remove('on')};
const left=keys.left?1:0,right=keys.right?1:0;const axis=right-left;state.playerX=THREE.MathUtils.clamp(state.playerX+axis*dt*5.4,-3.5,3.5);if(state.playerJump>0||state.jumpVel>0){state.playerJump+=state.jumpVel*dt;state.jumpVel-=14*dt;if(state.playerJump<0){state.playerJump=0;state.jumpVel=0}}player.position.x+=(state.playerX-player.position.x)*Math.min(1,dt*14);player.position.y=state.playerJump;
// Rival tracks the ball with imperfect anticipation.
if(state.ballMode==='flight'){let desired=THREE.MathUtils.clamp(ball.position.x+(ball.position.z>-1?state.ballVel.x*.1:0),-3.25,3.25);if(ball.position.z<-1)state.rivalX+=(desired-state.rivalX)*Math.min(1,dt*1.7);else state.rivalX+=(Math.sin(now*1.35)*1.5-state.rivalX)*Math.min(1,dt*.65)}else state.rivalX+=(Math.sin(now*.8)*.45-state.rivalX)*Math.min(1,dt*.5);rival.position.x=state.rivalX;
if(state.ballMode==='flight'){state.ballVel.x+=state.wind*dt;state.ballVel.y-=9.8*dt;state.ballPos.addScaledVector(state.ballVel,dt);if(state.ballPos.x>4.12||state.ballPos.x<-4.12)state.ballVel.x*=-.66;
// net collision: anything low enough clips the mesh and drops back
if(Math.abs(state.ballPos.z)<.18&&state.ballPos.y<2.42){state.ballVel.z*=-.48;state.ballVel.y=Math.max(-1,state.ballVel.y*.45);state.ballPos.z=Math.sign(state.ballPos.z||1)*.19;toast('NET!');}
if(state.ballVel.z<0&&state.ballPos.z<-1.35&&state.ballPos.z>-1.6){if(Math.abs(state.ballPos.x-state.rivalX)<1.55&&state.ballPos.y<3.35){rivalHit()}else if(state.ballPos.z< -1.6&&state.ballPos.y<3.5){/* rival saves if close later */}}
if(state.ballPos.z<-6.8&&state.ballPos.y<.34){point(0,state.ballPos.distanceTo(new THREE.Vector3(state.targetX,0,state.targetZ))<1.05)}else if(state.ballPos.z>6.8&&state.ballPos.y<.34){point(1)}else if(state.ballPos.y<.28){const side=state.ballPos.z<0?0:1;point(side===0?1:0)}
if(state.ballPos.z<-6.4&&state.ballVel.z<0&&state.ballPos.y<2.4){/* keep going until landing */}if(state.ballPos.z<-1.5&&state.ballPos.z>-5.9&&state.ballVel.z<0&&Math.abs(state.ballPos.x-state.rivalX)<1.1&&state.ballPos.y<2.65&&Math.random()<dt*1.9){rivalHit()}
setBall(...state.ballPos.toArray());ball.rotation.x+=dt*5;ball.rotation.z+=dt*6;ballMat.emissiveIntensity=.1+Math.max(0,(2.3-state.ballPos.y))*.1;
}else if(state.ballMode==='idle'){state.ballPos.set(state.playerX,3.5,4.2);setBall(...state.ballPos.toArray())}
// day-night palm breezes and target glides along the far backcourt
const targetEase=Math.sin(now*.44)*2.65;targetGroup.position.set(targetEase,0,-4.55+Math.cos(now*.31)*.72);state.targetX=targetGroup.position.x;state.targetZ=targetGroup.position.z;targetRing.material.color.setHex(state.wind?0xffa970:0xffd66d);targetRing.scale.setScalar(1+Math.sin(now*3)*.035);windVane.rotation.y=Math.sin(now*.9)*.22;windVane.rotation.z=state.wind*.1;
// pose and life
for(const [g,x,speed] of [[player,axis,10],[rival,0,8]]){const p=g.userData;for(const arm of p.arms){arm.rotation.z=(arm.name==='leftArm'?-1:1)*(.05+(state.ballMode==='flight'&&ball.position.distanceTo(g.position)<2.7?.65:Math.abs(x)*.24));arm.rotation.x=Math.sin(now*speed+(arm.name==='leftArm'?0:Math.PI))*.11}for(const leg of p.legs)leg.rotation.x=Math.sin(now*speed+(leg.name==='leftLeg'?0:Math.PI))*Math.abs(x)*.35;g.rotation.z=-x*.035} }
const keys={left:false,right:false};
function bindHold(el,onDown,onUp){el.addEventListener('pointerdown',e=>{e.preventDefault();el.classList.add('pressed');el.setPointerCapture?.(e.pointerId);onDown()});const up=e=>{el.classList.remove('pressed');onUp()};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up)}
document.querySelectorAll('[data-dir]').forEach(el=>{bindHold(el,()=>{keys[el.dataset.dir]=true},()=>{keys[el.dataset.dir]=false})});$('#hitBtn').addEventListener('pointerdown',e=>e.preventDefault());bindHold($('#hitBtn'),()=>{state.ballMode==='idle'?serve():volley()},()=>{});
$('#jumpBtn').addEventListener('pointerdown',e=>e.preventDefault());bindHold($('#jumpBtn'),()=>{if(state.playerJump===0){state.jumpVel=6.2}},()=>{});
$('#startBtn').onclick=startMatch;$('#pauseBtn').onclick=()=>{if(!state.running)return;state.paused=!state.paused;$('#pauseBtn').textContent=state.paused?'▶':'Ⅱ';if(state.paused){$('#card').innerHTML='<div class="eyebrow">CATCH YOUR BREATH</div><h1>TIME<br><em>OUT</em></h1><p>The tide waits for no one. Ready to get back on court?</p><button class="start-btn" id="resumeBtn">RESUME MATCH　↗</button><div class="micro">TOUCH CONTROLS · FIRST TO 5</div>';$('#overlay').classList.remove('hidden');$('#resumeBtn').onclick=()=>{$('#overlay').classList.add('hidden');state.paused=false;$('#pauseBtn').textContent='Ⅱ'}}else{$('#overlay').classList.add('hidden')}};
$('#soundBtn').onclick=()=>{state.sound=!state.sound;$('#soundBtn').style.opacity=state.sound?'1':'.5';toast(state.sound?'SOUND ON':'SOUND OFF')};
window.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=true;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=true;if(e.code==='Space'){e.preventDefault();state.ballMode==='idle'?serve():volley()}if(e.key.toLowerCase()==='w'||e.key==='ArrowUp')state.jumpVel=state.playerJump===0?6.2:state.jumpVel});window.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=false;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=false});
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<600?48:43;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,100));
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),now=performance.now()/1000;update(dt,now);if(state.shake>0){state.shake=Math.max(0,state.shake-dt);camera.position.x=Math.sin(now*90)*state.shake*.2}else camera.position.x+=(0-camera.position.x)*Math.min(1,dt*2);renderer.render(scene,camera)}
setupServe();animate();
</script>
</body>
</html>

