const state={running:false,paused:false,score:[0,0],ballMode:'idle',serveSide:0,serveAt:0,ballPos:new THREE.Vector3(),ballVel:new THREE.Vector3(),playerX:0,rivalX:0,jump:0,jumpV:0,hitLock:0,wind:0,windUntil:0,nextWind:0,rally:1};const keys={left:false,right:false};let toastTimer;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1250)}function setBall(){ball.position.copy(state.ballPos);ballShadow.position.set(state.ballPos.x,-.14,state.ballPos.z)}function updateHitLabel(){const hit=$('#hit');hit.textContent=state.ballMode==='idle'?(state.serveSide===0?'SERVE':'WAIT'):'VOLLEY';hit.style.opacity=state.ballMode==='idle'&&state.serveSide===1?'.55':'1'}
function setupServe(side){state.serveSide=side;state.ballMode='idle';state.serveAt=performance.now()/1000+(side?1.15:0);state.ballPos.set(side?state.rivalX:state.playerX,3.4,side?-4.15:4.15);state.ballVel.set(0,0,0);setBall();updateHitLabel();$('#tip').innerHTML=side?'<span>RIVAL SERVES</span> Move and volley it back!':'<span>YOUR SERVE</span> Tap the big button to launch.'}
function startMatch(){state.score=[0,0];state.rally=1;state.playerX=0;state.rivalX=0;state.wind=0;state.nextWind=performance.now()/1000+5;state.running=true;state.paused=false;$('#scoreMe').textContent='0';$('#scoreRival').textContent='0';$('#rallyNo').textContent='01';$('#overlay').classList.add('hidden');$('#pause').textContent='Ⅱ';setupServe(0);toast('FIRST TO 5 · GOLDEN POCKET = BONUS')}
function endMatch(){state.running=false;const win=state.score[0]>state.score[1];$('#card').innerHTML=`<div class="eyebrow">${win?'ISLAND CHAMPION':'THE TIDE TURNS'}</div><h1>${win?'YOU<br><em>WIN</em>':'NICE<br><em>RALLY</em>'}</h1><p>${win?'The golden pocket is yours. The island lights are all yours tonight.':'The locals hold the court this round. Ready for a rematch?'}</p><div class="feature">🏐　FINAL SCORE <b>${state.score[0]} — ${state.score[1]}</b></div><button class="start" id="restart">PLAY AGAIN　↗</button><div class="micro">TIDEBREAK · ISLAND VOLLEY CLUB</div>`;$('#overlay').classList.remove('hidden');$('#restart').onclick=startMatch}
function point(winner,bonus=false){if(!state.running||state.ballMode==='point')return;state.score[winner]=Math.min(5,state.score[winner]+(bonus?2:1));$('#scoreMe').textContent=state.score[0];$('#scoreRival').textContent=state.score[1];state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0');state.ballMode='point';toast(winner===0?(bonus?'GOLDEN POCKET! +2':'YOUR POINT!'):(bonus?'RIVAL +2':'RIVAL POINT'));if(state.score[winner]>=5){setTimeout(endMatch,1300);return}setTimeout(()=>{if(state.running)setupServe(winner===0?1:0)},850)}
function serve(){if(!state.running||state.paused||state.ballMode!=='idle'||state.serveSide!==0)return;state.ballMode='flight';state.ballPos.set(state.playerX,3.15,3.95);state.ballVel.set((target.position.x-state.playerX)*.27,5.6,-8.5);updateHitLabel();$('#tip').innerHTML='<span>MOVE + VOLLEY</span> Aim for the moving gold pocket!'}
function volley(){if(!state.running||state.paused||state.ballMode!=='flight'||state.hitLock>0)return;const xGap=Math.abs(ball.position.x-state.playerX),z=ball.position.z;if(z<.25||z>3.9||xGap>1.8||ball.position.y>4.5||ball.position.y<.45){if(z>0&&z<4)toast('GET UNDER THE BALL');return}state.hitLock=.55;state.ballVel.set((target.position.x-ball.position.x)*.5+(state.playerX-state.rivalX)*.24,5.4,-9.6);state.ballPos.z=Math.min(state.ballPos.z,3.3);state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0');toast('CLEAN RETURN')}
function rivalHit(){if(state.ballMode!=='flight')return;state.ballVel.set((state.playerX-ball.position.x)*.32,4.9,9.3);state.ballPos.z=-.75;state.hitLock=.18;state.rally++;$('#rallyNo').textContent=String(state.rally).padStart(2,'0')}
function gust(now){state.wind=(Math.random()<.5?-1:1)*(.9+Math.random()*1.25);state.windUntil=now+3.1;state.nextWind=now+8+Math.random()*3;$('#windText').textContent=`TIDAL GUST · ${state.wind>0?'→':'←'}`;$('#wind').classList.add('on');toast(state.wind>0?'GUST FROM THE LEFT →':'← GUST FROM THE RIGHT')}
function update(dt,now){if(!state.running||state.paused)return;state.hitLock=Math.max(0,state.hitLock-dt);if(state.ballMode==='idle'&&state.serveSide===1&&now>=state.serveAt){state.ballMode='flight';state.ballPos.set(state.rivalX,3.2,-4.05);state.ballVel.set((state.playerX-state.rivalX)*.25,5.4,8.4);updateHitLabel()}if(now>state.nextWind&&now>state.windUntil)gust(now);if(state.wind&&now>state.windUntil){state.wind=0;$('#wind').classList.remove('on')}
const axis=(keys.right?1:0)-(keys.left?1:0);state.playerX=THREE.MathUtils.clamp(state.playerX+axis*5.2*dt,-3.55,3.55);if(state.jump>0||state.jumpV>0){state.jump+=state.jumpV*dt;state.jumpV-=14*dt;if(state.jump<0){state.jump=0;state.jumpV=0}}player.position.x+=(state.playerX-player.position.x)*Math.min(1,dt*12);player.position.y=state.jump;
if(state.ballMode==='flight'){let desired=THREE.MathUtils.clamp(ball.position.x,-3.2,3.2);if(ball.position.z<-.6)state.rivalX+=(desired-state.rivalX)*Math.min(1,dt*1.55);else state.rivalX+=(Math.sin(now*1.2)*1.1-state.rivalX)*Math.min(1,dt*.7)}else state.rivalX+=(Math.sin(now*.8)*.35-state.rivalX)*Math.min(1,dt*.5);rival.position.x=state.rivalX;
if(state.ballMode==='flight'){state.ballVel.x+=state.wind*dt;state.ballVel.y-=9.8*dt;state.ballPos.addScaledVector(state.ballVel,dt);if(Math.abs(state.ballPos.x)>4.12)state.ballVel.x*=-.65;
if(Math.abs(state.ballPos.z)<.16&&state.ballPos.y<2.4){state.ballVel.z*=-.45;state.ballVel.y=Math.max(-1,state.ballVel.y*.4);state.ballPos.z=Math.sign(state.ballPos.z||1)*.18;toast('NET!')}
if(state.ballVel.z<0&&state.ballPos.z<-.65&&state.ballPos.z>-1.25&&Math.abs(state.ballPos.x-state.rivalX)<1.45&&state.ballPos.y<3.45){rivalHit()}
if(state.ballVel.z<0&&state.ballPos.z<-.8&&state.ballPos.z>-5.9&&Math.abs(state.ballPos.x-state.rivalX)<1.05&&state.ballPos.y<2.6&&Math.random()<dt*1.8){rivalHit()}
